// ko — 한국어.
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// TOM: **해요체** — o registro cortês-informal, que é o que app de amigos usa em coreano. Não é a
// mesma escolha de "tu contra você" das línguas europeias: o coreano marca a cortesia no VERBO, e
// são vários níveis. O 합쇼체 (…하십시오) é o de aviso de banco e aeroporto; o 해체 (반말, …해) é de
// quem tem intimidade, e um app usando-o com quem acabou de chegar soa atrevido. O 해요체 (…해요,
// …하세요) é o meio: educado sem ser distante. É o que Discord e KakaoTalk usam.
//
// VOCABULÁRIO, decidido uma vez: comunidade = 커뮤니티, canal = 채널, sala de voz = 음성 채널,
// mensagem = 메시지, senha = 비밀번호, transmissão = 방송, lixeira = 휴지통, tópico = 스레드.

