  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': '날짜를 입력한 사람의 생일에 Syden이 고른 채널에 축하 글을 올려요. 이름 대신 {pessoa}를 쓰세요.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': '일과 월만, 연도는 절대 묻지 않아요. 생일을 알리는 커뮤니티가 당일에 축하해요. 선택 사항이고, 언제든 지울 수 있어요.',
