  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': '메시지가 올라가기 전에 Syden이 스스로 적용하는 규칙이에요. 관리자는 적용되지 않아요. 막힌 메시지는 이유와 함께 쓴 사람에게 돌아가고, 다른 누구도 보지 못해요.',
