  'A comunidade já conquistou o selo, e quem administra ainda não escolheu qual será.': '커뮤니티는 이미 배지를 얻었고, 운영하는 사람이 아직 어떤 배지일지 고르지 않았어요.',
  'Abrir a transmissão sozinha': '방송만 따로 열기',
