  'Adicionar som': '사운드 추가',
  'Administradores podem apagar mensagens de qualquer pessoa, gerenciar todos os canais, emojis e sons desta comunidade e remover membros. Só o dono dá e tira esse cargo.': '관리자는 누구의 메시지든 지울 수 있고, 이 커뮤니티의 모든 채널과 이모지와 사운드를 관리하고, 멤버를 내보낼 수 있어요. 그 권한은 소유자만 주고 뺏을 수 있어요.',
  'Ajustar o avatar': '아바타 맞추기',
  'alguém': '누군가',
  'Alto-falante ou fone': '스피커 또는 헤드폰',
  'Apaga a comunidade para todo mundo, com os canais, as mensagens, os emojis e os sons dela. Não dá para desfazer.': '커뮤니티를 모두에게서 지워요. 채널, 메시지, 이모지, 사운드까지 함께요. 되돌릴 수 없어요.',
  'Apagar {comunidade} para todos os {quantos} membros? Os canais, as mensagens, os emojis e os sons somem junto.': '{comunidade}을(를) 멤버 {quantos}명 모두에게서 지울까요? 채널, 메시지, 이모지, 사운드도 같이 사라져요.',
  'Apagar comunidade': '커뮤니티 지우기',
