  'Colar imagem': '이미지 붙여넣기',
  'Como administrador, você pode remover membros que não são administradores.': '관리자로서, 관리자가 아닌 멤버를 내보낼 수 있어요.',
  'Como dono, você escolhe quem administra e pode remover qualquer pessoa.': '소유자로서, 누가 관리할지 고르고 누구든 내보낼 수 있어요.',
  'Confete, fogos e corações que qualquer pessoa da sala pode mandar. Desligue se o seu computador engasgar durante a chamada — desligado, você não vê nem manda.': '방에 있는 누구나 보낼 수 있는 색종이, 불꽃, 하트예요. 통화 중에 컴퓨터가 버거우면 꺼 두세요 — 꺼 두면 보이지도 않고 보내지도 않아요.',
  'Definir a minha senha': '내 비밀번호 설정',
  'Definir uma senha': '비밀번호 설정하기',
  'Desconecta o Syden em todos os outros computadores e celulares. Você continua conectado aqui.': '다른 컴퓨터와 휴대폰에서 Syden을 모두 로그아웃해요. 여기서는 그대로 있어요.',
