  'Modificador de voz': '음성 변조',
  'Muda como os outros ouvem você na chamada. Vale na hora, dá para trocar durante a conversa — e acaba quando você sai da sala: na próxima você entra com a sua voz.': '통화에서 다른 사람이 나를 어떻게 듣는지 바꿔요. 바로 적용되고, 대화 중에도 바꿀 수 있어요 — 그리고 방에서 나가면 끝나요. 다음에는 원래 목소리로 들어와요.',
  'Nada faltando: o pacote está completo.': '빠진 게 없어요. 꾸러미가 완전해요.',
