  'O navegador bloqueou as notificações deste site. Libere no cadeado ao lado do endereço e recarregue a página.': '브라우저가 이 사이트의 알림을 막았어요. 주소 옆 자물쇠에서 허용하고 페이지를 새로 고치세요.',
  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.': '첫 번째 이정표가 떨어지면 배지가 여기에 나타나요. 그때까지는 보관돼 있어요 — 거기까지 가는 게 바로 그 배지의 뜻이 될 거예요.',
  'Outros aparelhos': '다른 기기',
  'Ouvir': '들어보기',
  'Pacote do Syden': 'Syden 꾸러미',
  'Parar teste': '테스트 멈추기',
