  'Processamento de voz': '음성 처리',
  'Quem tiver este código entra na comunidade: pela tela de cadastro, se ainda não tem conta, ou pelo botão de entrar, se já usa o Syden.': '이 코드를 가진 사람은 커뮤니티에 들어와요. 계정이 아직 없으면 가입 화면에서, 이미 Syden을 쓰고 있으면 참여 버튼으로요.',
  'Reduz barulhos de fundo, como teclado, ventilador e trânsito.': '키보드, 선풍기, 차 소리 같은 배경 소음을 줄여요.',
