  'Senha alterada. Os outros aparelhos foram desconectados.': '비밀번호를 바꿨어요. 다른 기기는 로그아웃됐어요.',
  'Senha definida. Agora dá para entrar com nome e senha também.': '비밀번호를 정했어요. 이제 이름과 비밀번호로도 들어올 수 있어요.',
  'Serve para recuperar a senha e para avisar você se algo acontecer com o Syden. Sem e-mail, uma senha esquecida não tem volta.': '비밀번호를 되찾고, Syden에 무슨 일이 생기면 알려주는 데 써요. 이메일이 없으면 잊어버린 비밀번호는 돌아올 길이 없어요.',
  'Sons da comunidade': '커뮤니티 사운드',
