  'Testar microfone': '마이크 테스트',
  'Tirar o selo': '배지 떼기',
  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.': '누가 방에 들어오거나 나갈 때, 누가 화면 공유를 시작할 때, 그리고 내가 음소거하거나 소리를 끌 때 소리가 나요.',
  'Tocando…': '재생 중…',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.': '이 커뮤니티의 모두가 {exemplo} 라고 쓰거나 채팅의 이모지 버튼으로 이 이모지들을 쓸 수 있어요. 구독 없이 전부 열려 있어요.',
  'Traz de volta os emojis que vêm com o Syden. O que vocês enviaram continua como está, e nada vira cópia repetida.': 'Syden에 기본으로 들어 있는 이모지를 되돌려요. 여러분이 올린 건 그대로 남고, 중복으로 복사되지도 않아요.',
  'Trocar áudio': '오디오 바꾸기',
  'Trocar avatar': '아바타 바꾸기',
  'Usar este coelho': '이 토끼 쓰기',
  'Trocar imagem': '이미지 바꾸기',
  'Trocar o e-mail': '이메일 바꾸기',
  'Trocar senha': '비밀번호 바꾸기',
  'Veja se o microfone está captando a sua voz.': '마이크가 목소리를 잡고 있는지 보세요.',
  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.': '아직 하나도 없어요. 선물이나 보상으로 와요 — 예를 들어 당신의 아이디어가 Syden에 들어갔을 때요.',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.': '바깥 서비스로 들어와서 이 계정에는 아직 비밀번호가 없어요. 여기서 하나 정해 두세요. 두 번째 로그인 방법이 되고, 나중에 그 서비스를 끊을 수 있게 해주는 것도 이거예요.',
  'Você perde o acesso aos canais desta comunidade. Para voltar, vai precisar de um convite novo.': '이 커뮤니티의 채널에 들어갈 수 없게 돼요. 돌아오려면 새 초대가 필요해요.',
  'ZECA': '민수',
  '{email} — ainda não confirmado': '{email} — 아직 확인 안 됐어요',
  '{email} — confirmado': '{email} — 확인됐어요',
  'Clique para escolher quais aparecem no seu perfil (até {limite}).': '프로필에 어떤 걸 보여줄지 눌러서 골라요 (최대 {limite}개).',
  'Pessoas bloqueadas': '차단한 사람',
  'Quem está aqui não vê as suas mensagens nem você as dele, não consegue abrir conversa privada com você e não pode te mandar pedido de amizade.': '여기 있는 사람은 당신의 메시지를 보지 못하고 당신도 그들의 메시지를 보지 못해요. 당신과 개인 대화를 열 수 없고, 친구 요청도 보낼 수 없어요.',
  '{quantos} sons enviados por vocês': '여러분이 올린 사운드 {quantos}개',
  '1 som enviado por vocês': '여러분이 올린 사운드 1개',
