  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': '아래 이정표들은 혼자서는 닿을 수 없게 골랐어요 — 하나하나가 한 사람 이상을, 그리고 시간을 필요로 해요.',
