  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.': '꺼 두면 방에 있는 사람의 방송이 초대처럼 보이고, 보기를 눌러야 받기 시작해요. 인터넷과 프로세서를 아껴요 — 특히 사람이 많은 방에서요.',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.': '통화 중에 그 버튼이 이 사운드를 방에 있는 모두에게 들려줘요. 만들어진 꾸러미를 설치하거나 직접 올려요. 가장 좋아하는 건 패널 앞쪽에 있어요.',
