  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': '밤에는 다른 늑대인간들과 함께 누구를 공격할지 골라요. 낮에는 아무도 의심하지 않게 하세요.',
