  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': '밤에는 누군가가 늑대인간인지 알아봐요. 위험을 감수할 만하다고 생각되면 낮에 알려 주세요.',
  'Anjo': '천사',
