  'Da vila': '마을 주민',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': '밤에는 잠을 자요. 낮에는 누가 늑대인간인지 찾아내고 투표로 게임에서 내보내세요.',
  'A vila venceu!': '마을이 이겼어요!',
  'Os lobisomens venceram!': '늑대인간이 이겼어요!',
