  'Ninguém morreu esta noite.': '오늘 밤에는 아무도 죽지 않았어요.',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': '{n}일째 낮. 이야기를 나누고 늑대인간이라고 생각하는 사람에게 투표하세요.',
