  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': '먼저 멤버에서 커뮤니티 역할을 만드세요. 그다음 여기로 돌아오면 자동으로 나눠 줄 수 있어요.',
