  'Toda pessoa nova recebe estes cargos ao entrar na comunidade.': '새로 들어온 사람은 모두 커뮤니티에 들어올 때 이 역할들을 받아요.',
  'Cargos por reação': '반응 역할',
  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden이 채널에 역할마다 이모지가 하나씩 달린 메시지를 올려요. 반응하면 역할을 받고, 반응을 지우면 역할이 사라져요.',
  'Apagar o painel': '패널 삭제',
