  'Quais jogos a turma joga, com quantas pessoas e quantas partidas vão até o fim. Só contagem: respostas e desenhos não são guardados. Conta a partir de 12/10/2026.': '친구들이 어떤 게임을 몇 명이서 하는지, 몇 판이 끝까지 가는지 보여 줘요. 횟수만 세고, 답과 그림은 저장하지 않아요. 2026/10/12부터 집계해요.',
