  'A música': '노래',
  'O emoji': '이모지',
  'O arquivo': '파일',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}»({onde}) 항목이 Syden에서 내려갔어요. {quem} 측이 권리를 가지고 있다고 했기 때문이에요. 게시할 권한이 있었다면 여기에 답장해서 알려 주세요. 답장은 판단에 반영돼요. 확인될 때까지는 내려간 상태로 있어요. 어떻게 처리되는지는 약관 4조에 설명되어 있어요: https://syden.chat/termos.html#direito-autoral',
  '«{nome}» saiu.': '«{nome}» 항목을 내렸어요.',
