  'Direito autoral': '저작권',
  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': '권리자는 direitos@syden.chat으로 무엇이 어디에 있는지 적어 보내요. 이름으로 찾아서 내리면, 올린 사람은 관리자와의 개인 대화로 알림을 받고 거기서 이의를 제기할 수 있어요.',
