  'Tickets': '티켓',
  'Quem precisa falar com a administração abre um ticket no início da comunidade, com um assunto. Ele vira uma conversa privada em grupo entre essa pessoa e quem administra, e aparece na lista de conversas de vocês.': '관리자와 이야기해야 하는 사람은 커뮤니티 첫 화면에서 제목을 적어 티켓을 열어요. 티켓은 그 사람과 관리자들의 비공개 그룹 대화가 되고, 대화 목록에 나타나요.',
