  'O Syden é para quem tem 13 anos ou mais. Ninguém vê a sua data.': 'Syden은 13세 이상만 사용할 수 있어요. 생년월일은 아무도 볼 수 없어요.',
  'O Syden passou a pedir a idade de todo mundo, para proteger quem tem menos de 18 anos (a lei do ECA Digital). Ninguém vê a sua data: só a faixa de idade é usada.': '18세 미만을 보호하기 위해(ECA Digital 법) Syden은 이제 모든 사람에게 나이를 물어요. 생년월일은 아무도 볼 수 없고, 나이대만 사용돼요.',
