  'Quem tem de 13 a 15 anos usa o Syden com a conta ligada à de um pai, mãe ou responsável. É a lei (ECA Digital), e é para a sua segurança.': '13~15세는 부모님이나 보호자의 계정과 연결된 계정으로 Syden을 사용해요. 법(ECA Digital)이 정한 것이고, 안전을 위한 거예요.',
  'Quem tem menos de 18 anos usa o Syden com proteções a mais, e de 13 a 15 anos com a conta ligada à de um responsável (a lei do ECA Digital).': '18세 미만은 추가 보호와 함께 Syden을 사용하고, 13~15세는 계정을 보호자의 계정과 연결해요(ECA Digital 법).',
