  'Guarde onde fica cada pote e ponha todos de volta no lugar.': '항아리 위치를 기억해서 모두 제자리에 돌려놓으세요.',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': '위에서 호박이 굴러와요. 올라가면서 줄을 바꿔 피하세요!',
