  'Ouça, repita a batida no mesmo ritmo e acrescente uma no fim.': '잘 듣고, 같은 리듬으로 따라 친 다음 마지막에 하나를 더하세요.',
  'Paiol': '곡식 창고',
  'Pare cada faixa com o retrato no lugar, de cima para baixo.': '위에서부터 한 줄씩, 그림이 맞는 자리에서 멈추세요.',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': '세 릴을 같은 그림에 멈추세요. 세 개가 맞을 때마다 1점이에요.',
  'Pedras': '돌',
  'Pegue a galinha': '닭을 잡아라',
  'Pegue as cenouras no gelo e fuja dos repolhos.': '얼음 위의 당근을 줍고 양배추는 피하세요.',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': '황금 당근을 집어 울타리 문까지 가져가세요. 하나가 모자라요: 들고 있는 사람을 밀어요!',
