  'Pule do balanço para cair numa folha. A mais longe vale mais.': '그네에서 뛰어 잎 위에 내려앉으세요. 멀리 있는 잎일수록 점수가 커요.',
  'Pule quando o ponteiro passar. Ele fica cada vez mais rápido.': '바늘이 지나갈 때 뛰세요. 점점 빨라져요.',
