  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': '굴에서 굴로 움직이는 동물을 따라가세요. 마지막에 풍선을 든 동물이 어디 있는지 가리키세요.',
  'Silo': '사일로',
  'Solte o cipó quando ele estiver na faixa clara.': '덩굴이 밝은 띠에 있을 때 놓으세요.',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': '순무가 들판을 향할 때 놓으세요. 빨리 돌릴수록 멀리 날아가요.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': '풍향계까지 오르세요. 떨어지는 물건이나 까마귀에 닿으면 마지막으로 도착한 층으로 돌아가요.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': '움직이는 판자, 건초 더미, 들보를 밟고 헛간 꼭대기 풍향계까지 오르세요. 떨어지는 연장과 까마귀를 피하면서요. 혼자서는 시간과 친구들의 고스트와 겨뤄요.',
