  '{n} voltas': '{n}바퀴',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': '에너지는 체력이자 부스터: 가장자리에 부딪히면 줄고, 분홍색 띠에서 충전돼요.',
  'A nave explodiu: a energia acabou.': '기체가 폭발했어요: 에너지 소진.',
  'Posição: {posicao} de {total}': '순위: {total}명 중 {posicao}위',
  'Escolher a pista': '트랙 선택',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': '공중에 매달린 트랙을 달리는 당근 우주선 레이스, 카트보다 훨씬 빨라요. 에너지는 체력이자 부스터: 가장자리에 부딪히면 줄고, 분홍색 띠에서 충전되며, 트랙을 벗어나면 떨어져요. 혼자서는 시간과 친구들의 고스트와 겨뤄요.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': '닫힌 경기장 속 카트, 저마다 풍선 세 개. 상자를 먹고 아이템으로 다른 사람의 풍선을 터뜨려요: 풍선이 없으면 탈락, 끝까지 남은 사람이 승리.',
  'Esquadrilha da toca': '굴 비행대',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': '당근 비행기로 텃밭 해충과 맞서요: 씨앗을 피하고, 지원군을 챙기고, 마지막엔 기계 허수아비를 격추해요. 모두 같은 웨이브를 날고, 비행대 점수는 합산돼요.',
  'O espantalho caiu!': '허수아비 격추!',
  'A praga venceu desta vez.': '이번엔 해충이 이겼어요.',
