  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': '배를 고르고 바다를 터치하세요. 드래그하면 옮겨져요.',
  'Sortear a frota': '무작위 함대',
  'Sua frota já está pronta.': '함대가 이미 준비됐어요.',
  'Ponha todos os navios antes.': '먼저 배를 모두 배치하세요.',
