  'O navio não cabe aí.': '배가 거기에 들어가지 않아요.',
  'Os navios não podem encostar um no outro.': '배끼리 서로 닿을 수 없어요.',
  'Minigolfe 3D': '3D 미니골프',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': '경사로, 성, 풍차가 있는 3D 홀 여덟 개, 모두가 같은 홀을 동시에 쳐요. 드래그해서 조준하고 힘을 정한 뒤 놓으세요. 총 타수가 가장 적은 사람이 이겨요.',
  'Ver o buraco de cima': '홀을 위에서 보기',
  'Fora da pista! Mais uma tacada.': '코스 이탈! 한 타 추가.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': '옆으로 드래그해 조준하고 아래로 드래그해 힘을 정한 뒤 놓으세요. 키보드에서는 방향키로 조준하고, 스페이스를 누르고 있으면 힘이 정해져요.',
  'Futebol dos coelhos': '토끼 축구',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': '위에서 내려다보는 작은 경기장 축구예요. 공에 닿으면 드리블하고, 스페이스를 누르고 있으면 더 세게 슛하고, X로 패스해요. 방에서는 빈자리를 로봇이 채워요.',
  'Quantos por time?': '팀당 몇 명?',
  'Seu time venceu!': '우리 팀이 이겼어요!',
