  'Caça às pragas da horta': '텃밭 해충 사냥',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': '까마귀와 메뚜기가 텃밭을 공격해요. 도망가기 전에 조준하고 클릭해서 맞히세요. 탄약은 정해져 있고, 웨이브마다 더 빨라져요. 점수가 가장 높은 사람이 이겨요.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': '해충이 도망가기 전에 조준하고 클릭하세요. 한 발 쏠 때마다 당근이 하나 들어요.',
