  'Tacadas: {n}': '타수: {n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': '공을 뒤로 당겼다가 놓으세요. 키보드에서는 방향키로 조준하고, 스페이스를 누르고 있으면 힘이 정해져요.',
