  'Setas para correr, Espaço para pular (segure para ir mais alto).': '방향키로 달리기, 스페이스로 점프(길게 누르면 더 높이).',
  'Nenhum amigo jogou esta fase ainda.': '아직 이 스테이지를 플레이한 친구가 없어요.',
