  '{nome} achou {n} cenouras escondidas.': '{nome}님이 숨겨진 당근 {n}개를 찾았어요.',
  '{nome} trocou de lugar com {outro}.': '{nome}님과 {outro}님이 자리를 바꿨어요.',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': '인원이 부족해요: 경기가 일찍 끝나 트로피는 없어요.',
  'Saiu antes do fim': '끝나기 전에 나감',
  'Jogar o dado': '주사위 굴리기',
  '{nome} comprou a cenoura dourada!': '{nome}님이 황금 당근을 샀어요!',
  'Comprar a cenoura dourada por {preco} cenouras?': '당근 {preco}개로 황금 당근을 살까요?',
  'Comprar': '사기',
  '{nome} chegou à cenoura dourada.': '{nome}님이 황금 당근에 도착했어요.',
  'Quantas rodadas?': '몇 라운드 할까요?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': '토끼들이 여우, 까마귀, 오소리로부터 텃밭을 지켜요. 함께 움직이고, 콤보로 때리고, 서로 챙겨 주세요. 1~4명.',
  'Pulo do coelho': '토끼 점프',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': '달리고, 뛰고, 떨어지지 않는 플랫폼 레이스. 혼자서는 타임 어택으로 친구들의 고스트와, 다 같이는 실시간으로 한 스테이지 또는 세 스테이지 모두.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': '이웃한 채소 두 개를 바꿔 같은 것을 세 개 이상 맞추세요. 더미는 쉬지 않고 올라와요. 꼭대기에 닿지 않게 하세요. 다 같이 하면 연쇄와 콤보로 다른 사람에게 상자를 보내요.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': '미니골프 6홀, 모두 같은 홀을 동시에 쳐요. 공을 뒤로 당겼다가 놓으면 샷이에요. 총 타수가 가장 적은 사람이 이겨요.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': '차례대로 주사위를 굴려 텃밭을 돌아요. 당근을 모아 황금 당근을 사고, 라운드마다 다 같이 미니게임을 해요. 황금 당근이 가장 많은 사람이 이겨요.',
  'Os pódios e as conquistas da turma': '시상대와 친구들의 업적',
