  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': '브라질의 주도를 돌며 도시를 사고, 그곳에 멈춘 사람에게 임대료를 받으세요. 지역 전체를 모으면 건물을 지을 수 있어요. 거래하고, 경매에서 겨루고, 돈이 바닥나지 않게 하세요.',
