  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': '익숙한 도미노, 2~4명이 해요(4명이면 2인 1팀). 양 끝에 맞는 패를 이어 붙이고, 먼저 다 내려놓은 사람이 다른 사람들 손에 남은 점수를 가져가요.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': '상파울루식 트루코, 비라와 마닐랴 포함, 2명 또는 4명이 2인 1팀으로. 트루코를 외치고 6, 9, 12로 올리거나 포기하세요. 먼저 12점을 내면 이겨요.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': '브라질식 체커: 잡을 수 있으면 꼭 잡아야 하고(앞뒤 모두), 킹은 대각선 끝까지 움직여요. 방 사람들은 구경해요.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': '각자 함대를 숨기고 상대의 바다에 포를 쏴요. 맞히면 한 번 더. 상대 함대를 먼저 모두 침몰시키면 승리. 방 사람들은 구경해요.',
