  'Cozinha da toca': '굴속 주방',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': '상자에서 재료를 꺼내 도마에서 썰고, 태우지 않게 화구와 오븐에서 익힌 다음, 접시에 담아 창구에 내세요. 모두 같은 주문을 받아요. 3분 동안 접시를 가장 많이 낸 사람이 이겨요.',
  'Pegar ou largar': '들기 또는 놓기',
