  'Trinta segundos para montar uma ponte de madeira e aço. Ganha quem levar o tráfego até o outro lado gastando menos.': '나무와 강철로 다리를 놓는 데 30초. 가장 적은 비용으로 차들을 건너편까지 보낸 사람이 이겨요.',
