  // O fundo da câmera (16/11/2026)
  'Fundo da câmera': "카메라 배경",
  'Desfocado': "흐리게",
  'Apagado': "지우기",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "뒤에 보이는 것을 흐리게 하거나, 지우거나, 다른 것으로 바꿔요. 이를 위해 카메라 영상이 컴퓨터 밖으로 나가지 않아요.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "네이티브",
  'Resolução': "해상도",
  'Quadros por segundo': "초당 프레임",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "자동 선택이 틀릴 때를 위해: 해상도와 프레임은 방송 처음부터 끝까지 고른 그대로 유지돼요.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "목소리와 카메라 효과를 컴퓨터 안에서만 처리해요. 서버로는 아무것도 보내지 않아요.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "당근 코만도",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "친구들과 함께 달리며 쏘자: 당근 발사기는 여덟 방향으로 조준하고, 수류탄은 길을 열고, 우리에 갇힌 아기 토끼를 구하면 강화를 얻어. 마지막엔 드래곤이 기다려: 1~4명.",
  'Andar e mirar': "이동하고 조준",
  'Granada': "수류탄",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "굴 속 던전",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "버섯 왕의 굴을 함께 지나가요: 동물이 가득한 방, 갔다가 돌아오는 당근이 든 상자, 두 명이 동시에 눌러야 하는 버튼, 그리고 잠긴 문. 1~4명.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "굴 링",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "컴퓨터 상대 세 명과 겨루는 반사 신경 복싱. 펀치의 예고를 읽고 피하거나 막은 뒤 빈틈을 쳐. 장갑이 반짝일 때 치면 강펀치 별이 찬다.",
  'Esquivar': "피하기",
  'Abaixar e defender': "숙이기·막기",
  'Socar': "펀치",
  'Soco forte': "강펀치",
  'Aperte os socos para levantar!': "펀치를 연타해서 일어나!",
  'Lutas vencidas: {n}': "이긴 경기: {n}",
  'Nocaute!': "녹아웃!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "스타 루트",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "우주선을 탄 토끼들이 행성 지표를 지나 우주로: 쏘고, 길게 눌러 조준을 고정하고, 회전해서 총알을 튕겨 내고, 갈림길에서 길을 골라. 다 같이 같은 길을 날고, 끝에는 보스가 기다려.",
  'Pirueta': "회전",
  'Segure para travar a mira': "길게 눌러 조준 고정",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "텃밭 핀볼",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "텃밭의 핀볼 테이블: 스프링을 당기고, 양배추에 튕기고, 당근 세 개를 쓰러뜨리면 토끼 굴에 불이 들어와 공이 하나 더 나와. 공은 세 개, 너무 흔들면 테이블이 잠겨.",
  'Palhetas': "플리퍼",
  'Mola': "스프링",
  'Sacudir': "흔들기",
  'Bola salva!': "공 세이브!",
