  // Lendas da Toca (16/11/2026)
  'Lendas da Toca': "굴의 전설",
  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "짧은 턴제 RPG: 각자 파티의 영웅 한 명을 조종해요. 함께 고르고, 공격을 합치고, 성의 드래곤을 쓰러뜨리세요.",
  'Faísca': "불꽃",
