  'Acerta todos os inimigos.': "모든 적을 공격해요.",
  'Cura a turma e levanta quem caiu.': "파티를 치료하고 쓰러진 동료를 일으켜요.",
  'Um tiro forte, que passa da defesa.': "방어를 꿰뚫는 강한 한 발.",
  'Escolha o seu herói': "영웅을 고르세요",
  'Atacar': "공격",
  'Habilidade': "스킬",
  'Defender': "방어",
  'Combo': "콤보",
  'Dois ou mais no Combo atacam juntos.': "콤보를 고른 두 명 이상이 함께 공격해요.",
  'Equipar': "장착",
  'Deixar': "두기",
  // Bichos da Toca (16/11/2026)
  'Bichos da Toca': "굴속 동물",
  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "들판을 거닐며 풀숲의 동물들과 당근으로 친구가 되고, 최대 여섯 마리의 팀을 꾸려 보세요. 파란 집의 도전을 이기고, 방에서는 친구의 팀과 겨뤄 보세요.",
