  // Os mini-games e as insígnias (19/11/2026)
  "{nome} terminou uma Maravilha: defenda-a por 2 minutos!": "{nome}님이 불가사의를 완성했어요: 2분 동안 지켜내세요!",
  "{nome} terminou uma Maravilha.": "{nome}님이 불가사의를 완성했어요.",
  "A Maravilha da outra equipe ficou de pé por 2 minutos.": "상대 팀의 불가사의가 2분 동안 버텼어요.",
  "A Maravilha da sua equipe ficou de pé por 2 minutos.": "우리 팀의 불가사의가 2분 동안 버텼어요.",
  "A outra equipe derrubou os dois centros da vila de vocês.": "상대 팀이 우리 팀의 마을 회관 두 곳을 모두 무너뜨렸어요.",
  "A outra equipe desistiu.": "상대 팀이 기권했어요.",
  "A outra equipe saiu da sala.": "상대 팀이 방에서 나갔어요.",
  "A sua equipe desistiu.": "우리 팀이 기권했어요.",
  "A sua equipe ficou fora da sala por muito tempo.": "우리 팀이 방 밖에 너무 오래 있었어요.",
  "Duas equipes de dois. Os robôs completam os lugares que faltam.": "2명씩 두 팀. 빈자리는 로봇이 채워요.",
  "Gênero": "성별",
  "Levadiça": "도개교",
  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "아직 대화가 없어요. 커뮤니티 멤버 목록에서 누군가를 탭하고 '메시지 보내기'를 고르세요.",
  "Varia": "다양함",
  "Vitória de {nomes}": "{nomes} 승리",
  "Vocês derrubaram os dois centros da vila da outra equipe.": "상대 팀의 마을 회관 두 곳을 모두 무너뜨렸어요.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "아무도 사지 않은 도시는 경매로 넘어가요. 도시를 저당 잡히면 돈이 들어오지만, 그 도시에서는 임대료를 받을 수 없어요.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "힌트는 움직일 말을 밝혀 줘요. 힌트를 쓴 문제는 점수가 없고, 타임어택에서는 10초가 줄어요.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "마닐랴는 비라 바로 다음 숫자이고, 모든 카드를 이겨요. 마닐랴끼리는 약한 순으로 다이아, 스페이드, 하트, 클럽(자프)이에요.",
  "A última nave de cada volta sai.": "매 바퀴 꼴찌 기체가 탈락해요.",
  "Abaixar": "숙이기",
  "Acertos em sequência: {n}": "연속 정답: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "주사위만큼 이동하고 멈춘 수도를 사세요. 다른 사람의 도시에 멈추면 임대료를 내요.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "모든 가로줄, 세로줄, 3 × 3 블록에 1부터 9까지 숫자가 겹치지 않게 들어가요.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "각자 카드 3장을 받아요. 3라운드 중 2라운드를 이기면 그 판을 가져가요.",
  "Campeonato": "챔피언십",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "11점이 되면 그 팀은 카드를 보고 11점 판을 할지 정해요. 먼저 12점에 도달하면 이겨요.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "지역을 모두 가지면 건물을 4채까지 지을 수 있어요. 한 채마다 임대료가 올라요.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "별이 있으면 강펀치(★)가 별을 한꺼번에 다 쓰고 더 아파요.",
  "Dica": "힌트",
  "Dica: este problema não pontua": "힌트: 이 문제는 점수 없음",
  "Dica: tira 10 segundos": "힌트: 10초 감소",
  "Eliminação": "탈락전",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "테이블 끝에 같은 숫자의 패를 이어 붙이세요.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "칸을 고른 다음 숫자를 고르세요. 연필 메모는 본인에게만 보여요.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "펀치를 피하고 바로 치세요. 그게 카운터이고, 별을 받아요.",
  "Fora da corrida na volta {n}.": "{n}바퀴째에 탈락.",
  "Força das cartas": "카드 세기",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "라운드가 끝났을 때 자산이 가장 많은 사람, 또는 마지막까지 남은 사람이 이겨요.",
  "Iniciante": "입문",
  "Mestre": "마스터",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "연속 모드에서는 맞힐 때마다 더 어려운 문제가 나오고, 한 번 틀리면 끝나요.",
  "O número pequeno no botão diz quantos ainda faltam.": "버튼의 작은 숫자는 아직 몇 개 남았는지 알려 줘요.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "다섯 코스를 연달아 컴퓨터와 겨뤄요, 점수제로.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "트루코를 외치면 그 판은 3점이 돼요. 받는 쪽은 수락하거나, 포기하거나, 6, 9, 12로 올려요.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "패를 다 내려놓은 사람이 다른 사람들 손에 남은 점수를 가져가요. 막히면 손에 든 점수가 가장 적은 사람이 가져가요.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "낼 패가 없으면 가져오세요. 가져올 패도 없으면 차례가 넘어가요.",
