  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "비밀 동물이 하나 정해지고, 각자 다른 동물을 추측해요. 추측할 때마다 비밀 동물과 맞는 항목이 보여요: 강, 식성, 서식지, 무게. 적게 추측하고 맞힐수록 점수가 높아요.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "비밀 공룡이 하나 정해지고, 각자 다른 공룡을 추측해요. 추측할 때마다 비밀 공룡과 맞는 항목이 보여요: 시대, 식성, 무리, 몸길이, 발견된 곳. 적게 추측하고 맞힐수록 점수가 높아요.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "비밀 원소가 하나 정해지고, 각자 다른 원소를 추측해요. 추측할 때마다 비밀 원소와 맞는 항목이 보여요: 분류, 상태, 주기, 족, 원자 번호. 적게 추측하고 맞힐수록 점수가 높아요.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "브라질의 비밀 주가 하나 정해지고, 각자 다른 주를 추측해요. 추측할 때마다 비밀 주까지의 거리와 방향, 지역, 인구, 면적, 해안, 다른 나라와의 국경이 보여요. 적게 추측하고 맞힐수록 점수가 높아요.",
