  "Quem administra esta comunidade baniu a sua conta, e por isso não dá para entrar.": "이 커뮤니티의 관리자가 내 계정을 추방해서 들어갈 수 없어요.",
  "Só quem administra a comunidade pode banir alguém.": "커뮤니티 관리자만 다른 사람을 추방할 수 있어요.",
