  "Só quem administra a comunidade fixa mensagens.": "메시지는 커뮤니티 관리자만 고정할 수 있어요.",
  "Só as mensagens do canal podem ser fixadas, não as de um tópico.": "채널 메시지만 고정할 수 있고, 스레드 메시지는 고정할 수 없어요.",
  "Este canal já tem 50 mensagens fixadas. Desafixe uma antes.": "이 채널에는 이미 고정된 메시지가 50개 있어요. 먼저 하나를 고정 해제하세요.",
