  "Editar mensagem": "메시지 수정",
  "Canal de avisos: só quem administra escreve aqui. Para conversar sobre um aviso, abra um tópico nele.": "공지 채널: 여기에는 관리자만 글을 쓸 수 있어요. 공지에 대해 이야기하려면 그 공지에서 스레드를 열어 주세요.",
  "Canais de avisos": "공지 채널",
  "Num canal de avisos, só quem administra escreve. A turma lê, reage e conversa nos tópicos de cada aviso.": "공지 채널에서는 관리자만 글을 써요. 다른 사람들은 읽고, 반응하고, 각 공지의 스레드에서 이야기해요.",
  "{quem} fez de {canal} um canal de avisos": "{quem} 님이 {canal}을(를) 공지 채널로 만들었어요",
